SELECT id, job_no, name, phone, company, user_type, region, region_code, status, audit_status, create_time
FROM sys_user
WHERE is_deleted = 0 AND user_type != 'ADMIN'
AND name LIKE CONCAT('%', #{name}, '%')
AND job_no = #{jobNo}
AND user_type = #{userType}
AND status = #{status}
ORDER BY id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM sys_user
WHERE is_deleted = 0 AND user_type != 'ADMIN'
AND name LIKE CONCAT('%', #{name}, '%')
AND job_no = #{jobNo}
AND user_type = #{userType}
AND status = #{status}
